 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color == background:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            # Only a complete, one-cell-thick rectangular outline qualifies.
            border_ok = all(
                grid[y][x] == color
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            )
            interior = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)]
            if not border_ok or not all(grid[y][x] == background for y, x in interior):
                continue
            ih, iw = r1 - r0 - 1, c1 - c0 - 1
            fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
            for y, x in interior:
                out[y][x] = fill
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
